CREATE TEMP TABLE events (
  id VARCHAR DEFAULT tsid() PRIMARY KEY,
  action VARCHAR
);
INSERT INTO events(action) VALUES
  ('login'), ('click'), ('logout');
SELECT id, tsid_to_timestamp(id) AS created_utc
FROM events
ORDER BY id;

SELECT * FROM events
ORDER BY id DESC LIMIT 2;

SET VARIABLE cursor = (
  SELECT id FROM events
  ORDER BY id DESC LIMIT 1 OFFSET 1
);
SELECT * FROM events
WHERE id < getvariable('cursor')
ORDER BY id DESC LIMIT 2;
